import{_ as e,o as a,c as n,a2 as r}from"./chunks/framework.O93z6AWZ.js";const p=JSON.parse('{"title":"DETAILED COURSE SYLLABUS: MACHINE LEARNING IN HEALTHCARE","description":"","frontmatter":{},"headers":[],"relativePath":"en/syllabus.md","filePath":"en/syllabus.md"}'),i={name:"en/syllabus.md"};function l(s,t,o,d,c,g){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="detailed-course-syllabus-machine-learning-in-healthcare" tabindex="-1">DETAILED COURSE SYLLABUS: MACHINE LEARNING IN HEALTHCARE <a class="header-anchor" href="#detailed-course-syllabus-machine-learning-in-healthcare" aria-label="Permalink to &quot;DETAILED COURSE SYLLABUS: MACHINE LEARNING IN HEALTHCARE&quot;">​</a></h1><p><strong>Course code:</strong> ET4248 <strong>Course title:</strong> Học máy trong Y tế (Machine Learning in Healthcare) <strong>Duration:</strong> 03 Credits (teaching, corresponding to 18 lectures L01–L18) <strong>Intended audience:</strong> Undergraduate/graduate students in Biomedical Engineering, Electronics &amp; Telecommunications, Information Technology, and Health Data Science.</p><hr><h2 id="_1-course-learning-objectives-clo" tabindex="-1">1. COURSE LEARNING OBJECTIVES (CLO) <a class="header-anchor" href="#_1-course-learning-objectives-clo" aria-label="Permalink to &quot;1. COURSE LEARNING OBJECTIVES (CLO)&quot;">​</a></h2><p>Upon completing this course, learners will be able to:</p><ul><li><strong>CLO 1:</strong> Explain the foundational concepts of Machine Learning and the 4V characteristics of medical data; distinguish Supervised Learning, Unsupervised Learning, and Reinforcement Learning.</li><li><strong>CLO 2:</strong> Proficiently carry out exploratory data analysis (EDA), preprocessing, cleaning, and standardization of medical data (including the international DICOM, HL7/FHIR, EDF/WFDB, and LOINC standards).</li><li><strong>CLO 3:</strong> Build, train, and interpret the clinical meaning of classical machine-learning models: Linear Regression, Logistic Regression, the Odds Ratio, Support Vector Machines (SVM), Clustering (K-Means, GMM), and Dimensionality Reduction (PCA, ICA).</li><li><strong>CLO 4:</strong> Correctly apply regularization techniques (Ridge/Lasso), Stratified K-fold cross-validation, and evaluation metrics (Sensitivity, Specificity, ROC-AUC, F1, MCC) in the context of severe class imbalance and asymmetric error costs.</li><li><strong>CLO 5:</strong> Present and implement Multilayer Perceptron (MLP) and Convolutional Neural Network (CNN) architectures, along with modern optimization techniques (Adam, Batch Normalization, Dropout, Hyperparameter Tuning).</li><li><strong>CLO 6:</strong> Apply these models to real clinical problems (ECG arrhythmia classification, heart-failure prediction from EHR data, sepsis alerting, breast-cancer classification, intracranial-hemorrhage detection on CT); develop a deep awareness of AI ethics, explainability (XAI/SHAP), algorithmic bias, and the legal framework (Decree 13/2023/NĐ-CP, HIPAA, the EU AI Act, FDA guidance).</li></ul><hr><h2 id="_2-course-structure-8-chapters" tabindex="-1">2. COURSE STRUCTURE (8 CHAPTERS) <a class="header-anchor" href="#_2-course-structure-8-chapters" aria-label="Permalink to &quot;2. COURSE STRUCTURE (8 CHAPTERS)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Chapter</th><th style="text-align:left;">Chapter Title</th><th style="text-align:center;">Source Lectures</th><th style="text-align:left;">Focus &amp; Case Study</th><th style="text-align:center;">Link</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1</strong></td><td style="text-align:left;">Chapter 1: Overview &amp; AI Ethics</td><td style="text-align:center;">L01</td><td style="text-align:left;">The 4Vs of data, Taxonomy, Bias-Variance, Pipeline, AI Ethics (ECG MIT-BIH, Epic Sepsis, Obermeyer)</td><td style="text-align:center;"><a href="/hmyt-book/en/ch01">View Chapter 1</a></td></tr><tr><td style="text-align:center;"><strong>2</strong></td><td style="text-align:left;">Chapter 2: EHR Data Exploration &amp; Preprocessing</td><td style="text-align:center;">L02</td><td style="text-align:left;">EDA, Missing Data Handling (Rubin 1976), Outliers, Scaling, DICOM/HL7-FHIR Standards (Heart Failure Prediction)</td><td style="text-align:center;"><a href="/hmyt-book/en/ch02">View Chapter 2</a></td></tr><tr><td style="text-align:center;"><strong>3</strong></td><td style="text-align:left;">Chapter 3: Linear Models &amp; the Odds Ratio</td><td style="text-align:center;">L03, L04, L05</td><td style="text-align:left;">Linear Reg (MSE/Normal Eq), Logistic Reg (Cross-Entropy/Softmax), Odds Ratio (Hypertension, Atrial Fibrillation)</td><td style="text-align:center;"><a href="/hmyt-book/en/ch03">View Chapter 3</a></td></tr><tr><td style="text-align:center;"><strong>4</strong></td><td style="text-align:left;">Chapter 4: Regularization &amp; Clinical Evaluation</td><td style="text-align:center;">L06, L07, L08</td><td style="text-align:left;">Ridge/Lasso, Stratified K-fold, Data Leakage, Confusion Matrix, ROC-AUC (Biomarkers, Sepsis)</td><td style="text-align:center;"><a href="/hmyt-book/ch04">View Chapter 4 (VI)</a></td></tr><tr><td style="text-align:center;"><strong>5</strong></td><td style="text-align:left;">Chapter 5: Nonlinear Models &amp; SVM</td><td style="text-align:center;">L09, L10, L11</td><td style="text-align:left;">Basis functions, SVM (Soft Margin/Kernel Trick), Feature Selection (Filter/Wrapper/Embedded/mRMR) (Breast Cancer)</td><td style="text-align:center;"><a href="/hmyt-book/ch05">View Chapter 5 (VI)</a></td></tr><tr><td style="text-align:center;"><strong>6</strong></td><td style="text-align:left;">Chapter 6: Unsupervised Learning &amp; PCA/ICA</td><td style="text-align:center;">L012, L13, L14</td><td style="text-align:left;">K-Means, GMM/EM, PCA, ICA (Obstructive Sleep Apnea, ECG/EEG Denoising, Fetal ECG Extraction)</td><td style="text-align:center;"><a href="/hmyt-book/ch06">View Chapter 6 (VI)</a></td></tr><tr><td style="text-align:center;"><strong>7</strong></td><td style="text-align:left;">Chapter 7: Artificial Neural Networks (MLP)</td><td style="text-align:center;">L15, L16, L17</td><td style="text-align:left;">Forward/Backprop, Adam, Batch Norm, Dropout, Bayesian Tuning (Arrhythmia, Chest X-ray Pneumonia)</td><td style="text-align:center;"><a href="/hmyt-book/ch07">View Chapter 7 (VI)</a></td></tr><tr><td style="text-align:center;"><strong>8</strong></td><td style="text-align:left;">Chapter 8: Convolutional Networks (CNN) &amp; Medical Imaging</td><td style="text-align:center;">L18</td><td style="text-align:left;">Convolution, Receptive Field, Pooling, CNN Architectures (Intracranial Hemorrhage Detection on CT)</td><td style="text-align:center;"><a href="/hmyt-book/ch08">View Chapter 8 (VI)</a></td></tr></tbody></table><blockquote><p>Chapters 1–3 above are available in English; Chapters 4–8 link to the Vietnamese original (marked &quot;(VI)&quot;) until they are translated — see the <a href="/hmyt-book/">Full Course (Vietnamese)</a> for the complete syllabus in its original language.</p></blockquote>',10)])])}const u=e(i,[["render",l]]);export{p as __pageData,u as default};
